<?php
session_start(); require_once('check-login.php'); require_once('website-content-utils.php');
if(!isset($_SESSION['ACCESSLEVEL']) || $_SESSION['ACCESSLEVEL'] !== 'administrator'){ http_response_code(403); exit('Only system administrators can manage the public gallery.'); }
if(empty($_SESSION['website_gallery_csrf'])){ $_SESSION['website_gallery_csrf'] = bin2hex(random_bytes(32)); }
website_gallery_ensure_table($con); $message=''; $tone='ok';
if($_SERVER['REQUEST_METHOD'] === 'POST'){
 if(!hash_equals($_SESSION['website_gallery_csrf'], isset($_POST['csrf']) ? $_POST['csrf'] : '')){ $message='Your form expired. Please try again.'; $tone='bad'; }
 elseif(isset($_POST['delete_id'])){ if(website_gallery_delete($con,(int)$_POST['delete_id'])){ $message='Gallery photo removed.'; } else { $message='That gallery photo could not be removed.'; $tone='bad'; } }
 elseif(isset($_POST['upload_gallery_photo'])){ $caption=trim(isset($_POST['caption']) ? $_POST['caption'] : ''); $file=isset($_FILES['gallery_image']) ? $_FILES['gallery_image'] : null; $allowed=array('image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'); $mime=($file && $file['error']===UPLOAD_ERR_OK && function_exists('mime_content_type')) ? mime_content_type($file['tmp_name']) : '';
  if($caption==='' || !$file || $file['error']!==UPLOAD_ERR_OK || $file['size']>5242880 || !isset($allowed[$mime]) || @getimagesize($file['tmp_name'])===false){ $message='Add a caption and choose a JPG, PNG, or WebP image no larger than 5 MB.'; $tone='bad'; }
  else { $folder=__DIR__.DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'website'.DIRECTORY_SEPARATOR.'gallery'; if(!is_dir($folder) && !mkdir($folder,0755,true)){ $message='The gallery image folder could not be created.'; $tone='bad'; } else { $filename='gallery-'.date('Ymd-His').'-'.bin2hex(random_bytes(4)).'.'.$allowed[$mime]; $path='uploads/website/gallery/'.$filename; if(move_uploaded_file($file['tmp_name'],$folder.DIRECTORY_SEPARATOR.$filename)){ $stmt=mysqli_prepare($con,'INSERT INTO tblwebsitegallery (image_path, caption, uploaded_by) VALUES (?, ?, ?)'); $user=$_SESSION['USERID']; mysqli_stmt_bind_param($stmt,'sss',$path,$caption,$user); $saved=mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); if($saved){ $message='Gallery photo published.'; } else { @unlink($folder.DIRECTORY_SEPARATOR.$filename); $message='The gallery photo could not be saved.'; $tone='bad'; } } else { $message='The image could not be uploaded.'; $tone='bad'; } } }
 }
}
$items=website_gallery_items($con);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Gallery | AYISEC</title><link rel="stylesheet" href="css/font-awesome-4.7.0/css/font-awesome.min.css"><style>body{margin:0;background:#f3f6f8;color:#15283b;font:16px/1.5 Arial,sans-serif}.wrap{max-width:1050px;margin:38px auto;padding:0 20px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}h1,h2{margin:0 0 8px}.top a,.button{display:inline-block;padding:10px 15px;border:0;border-radius:7px;background:#0f4c75;color:#fff;text-decoration:none;font-weight:bold;cursor:pointer}.back{background:#fff!important;color:#183650!important;border:1px solid #d7e0e8!important}.card{background:#fff;border:1px solid #dce5eb;border-radius:10px;padding:24px;margin-bottom:20px}.msg{padding:13px 16px;border-radius:7px;margin-bottom:18px}.ok{background:#dcfce7;color:#166534}.bad{background:#fee2e2;color:#991b1b}label{display:block;font-weight:bold;margin:14px 0 6px}input{box-sizing:border-box;width:100%;padding:10px;border:1px solid #becbd5;border-radius:6px;font:inherit}.hint{font-size:13px;color:#64748b}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:15px}.item{border:1px solid #dce5eb;border-radius:8px;overflow:hidden;background:#fff}.item img{display:block;width:100%;height:155px;object-fit:cover}.item div{padding:10px}.item p{margin:0 0 9px;font-weight:bold}.remove{background:#b91c1c!important;font-size:13px!important;padding:8px 10px!important}.tag{font-size:12px;color:#64748b}@media(max-width:600px){.top{align-items:flex-start;flex-direction:column}}</style></head><body><main class="wrap"><div class="top"><div><h1>Manage Gallery</h1><p>Upload photos that will appear in the public school gallery.</p></div><div><a class="back" href="website-editor.php">Website editor</a> <a href="gallery.php" target="_blank">View gallery</a></div></div><?php if($message!==''){ ?><div class="msg <?php echo website_content_escape($tone); ?>"><?php echo website_content_escape($message); ?></div><?php } ?><section class="card"><h2>Add gallery photo</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?php echo website_content_escape($_SESSION['website_gallery_csrf']); ?>"><label>Caption</label><input name="caption" maxlength="180" required placeholder="e.g. Inter-house athletics day"><label>Photo</label><input type="file" name="gallery_image" accept="image/jpeg,image/png,image/webp" required><p class="hint">JPG, PNG, or WebP; maximum 5 MB.</p><button class="button" type="submit" name="upload_gallery_photo"><i class="fa fa-upload"></i> Upload to gallery</button></form></section><section class="card"><h2>Gallery photos</h2><p class="hint">Only photos marked “Managed” can be removed here. Older website photos are preserved.</p><div class="grid"><?php foreach($items as $item){ ?><article class="item"><img src="<?php echo website_content_escape($item['path']); ?>" alt="<?php echo website_content_escape($item['caption']); ?>"><div><p><?php echo website_content_escape($item['caption']); ?></p><span class="tag"><?php echo $item['managed'] ? 'Managed photo' : 'Existing website photo'; ?></span><?php if($item['managed']){ ?><form method="post" onsubmit="return confirm('Remove this gallery photo?');"><input type="hidden" name="csrf" value="<?php echo website_content_escape($_SESSION['website_gallery_csrf']); ?>"><input type="hidden" name="delete_id" value="<?php echo (int)$item['id']; ?>"><button class="button remove" type="submit">Remove</button></form><?php } ?></div></article><?php } ?></div></section></main></body></html>
